parameters.jsCode:
const telefone = String($('Edit Fields2').first().json.Telefone || '').replace(/\D/g, '');

let telefoneCorrigido = telefone;

if (telefone.length === 12 && telefone.startsWith('55')) {
  telefoneCorrigido = telefone.slice(0, 4) + '9' + telefone.slice(4);
}

return [
  {
    json: {
      Telefone: telefoneCorrigido,
    },
  },
];

